script:
(function () {
  'use strict';
  // Pension decisions, valued in dollars at the age the first payment starts. Payments are made
  // at the start of each month and rise by the cost-of-living adjustment (COLA) once a year.
  // The present value discounts month k at (1 + i)^-k with i = (1 + annual return)^(1/12) - 1:
  //   PV = sum over k of P x (1 + cola)^floor(k/12) / (1 + i)^k
  // Lump sum: compares PV with the lump sum, finds the return at which they are equal (bisection),
  // and runs the lump sum down with the same monthly payments to see when it would run out.
  // Survivor: single-life pays until your life expectancy; joint pays the joint amount until then,
  // then the survivor share until the spouse's life expectancy. Work longer: both pensions valued
  // at the earlier age; break-even age = when total dollars received under option 2 catch up.
  // CHECKS (Node, scratch tests): with no COLA, PV = P x (1 - v^n) / (1 - v): $3,000 a month for
  // 20 years at 5% = $460,699.66 (closed form); 0% return and 0% COLA -> PV = $3,000 x 240 =
  // $720,000; lump sum equal to PV gives an implied return equal to the input; a $500,000 lump
  // sum paying $3,000 a month at 0% lasts 166.7 months; work longer at 0% COLA: $2,400 from 62
  // vs $3,000 from 65 -> totals equal when 2,400 x m = 3,000 x (m - 36), m = 180 -> age 77.
  function monthlyRate(r) { return Math.pow(1 + r, 1 / 12) - 1; }

  // PV at month 0 of payments P (rising by cola yearly) for months [from, to), discounted at i.
  // The COLA year count starts at month `colaStart`.
  function pv(P, cola, i, from, to, colaStart) {
    var total = 0;
    for (var k = from; k < to; k++) {
      total += P * Math.pow(1 + cola, Math.floor((k - colaStart) / 12)) / Math.pow(1 + i, k);
    }
    return total;
  }

  // Annual return at which the pension is worth exactly the lump sum (null if outside -50%..100%).
  function impliedReturn(L, P, cola, months) {
    var lo = -0.5, hi = 1;
    var f = function (r) { return pv(P, cola, monthlyRate(r), 0, months, 0) - L; };
    if (L <= 0 || P <= 0 || months <= 0 || f(lo) < 0 || f(hi) > 0) return null;
    for (var n = 0; n < 100; n++) {
      var mid = (lo + hi) / 2;
      if (f(mid) > 0) lo = mid; else hi = mid;
    }
    return (lo + hi) / 2;
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var money = { format: function (x) { return moneyFmt.format(Math.abs(x) < 0.005 ? 0 : x); } };
  var pct = new Intl.NumberFormat('en-US', { style: 'percent', minimumFractionDigits: 1, maximumFractionDigits: 1 });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function fmtAge(a) { var y = Math.floor(a), m = Math.round((a - y) * 12); if (m === 12) { y += 1; m = 0; } return y + (m ? ' and ' + m + ' month' + (m > 1 ? 's' : '') : ''); }

  function lumpMode(o) {
    var months = (o.life - o.age) * 12, i = monthlyRate(o.ret);
    var value = pv(o.P, o.cola, i, 0, months, 0);
    // Run the lump sum down with the same payments.
    var bal = o.L, lastsMonths = null, rows = [], received = 0, yearPay = 0;
    for (var k = 0; k < (120 - o.age) * 12; k++) {
      var pay = o.P * Math.pow(1 + o.cola, Math.floor(k / 12));
      if (lastsMonths === null) {
        if (pay > bal + 1e-9) { lastsMonths = k + (pay > 0 ? bal / pay : 0); bal = 0; }
        else bal = (bal - pay) * (1 + i);
      }
      if (k < months) { yearPay += pay; received += pay; }
      if (k % 12 === 11 && k < months) {
        rows.push([o.age + (k + 1) / 12 - 1, yearPay, received, bal]);
        yearPay = 0;
      }
      if (k >= months && lastsMonths !== null) break;
    }
    return { value: value, rows: rows, lastsMonths: lastsMonths, implied: impliedReturn(o.L, o.P, o.cola, months), months: months };
  }

  function survivorMode(o) {
    var i = monthlyRate(o.ret), yours = (o.life - o.age) * 12, spouse = (o.spLife - o.spAge) * 12;
    var surv = o.joint * o.survPct;
    var single = pv(o.single, o.cola, i, 0, yours, 0);
    var joint = pv(o.joint, o.cola, i, 0, yours, 0) + (spouse > yours ? pv(surv, o.cola, i, yours, spouse, 0) : 0);
    var end = Math.max(yours, spouse), rows = [], cs = 0, cj = 0, ys = 0, yj = 0, totS = 0, totJ = 0;
    for (var k = 0; k < end; k++) {
      var f = Math.pow(1 + o.cola, Math.floor(k / 12));
      var s = k < yours ? o.single * f : 0;
      var j = k < yours ? o.joint * f : (k < spouse ? surv * f : 0);
      ys += s; yj += j; totS += s; totJ += j;
      if (k % 12 === 11 || k === end - 1) { rows.push([o.age + Math.floor(k / 12), ys, yj, totJ - totS]); ys = 0; yj = 0; }
    }
    return { single: single, joint: joint, rows: rows, totS: totS, totJ: totJ, surv: surv, survYears: Math.max(0, spouse - yours) / 12 };
  }

  function laterMode(o) {
    var i = monthlyRate(o.ret), gap = (o.age2 - o.age1) * 12;
    var m1 = (o.life - o.age1) * 12, m2 = (o.life - o.age2) * 12;
    var v1 = pv(o.pay1, o.cola, i, 0, m1, 0);
    var v2 = m2 > 0 ? pv(o.pay2, o.cola, i, gap, gap + m2, gap) : 0;
    var c1 = 0, c2 = 0, y1 = 0, y2 = 0, rows = [], breakEven = null;
    for (var k = 0; k < (120 - o.age1) * 12; k++) {
      var p1 = o.pay1 * Math.pow(1 + o.cola, Math.floor(k / 12));
      var p2 = k >= gap ? o.pay2 * Math.pow(1 + o.cola, Math.floor((k - gap) / 12)) : 0;
      c1 += p1; c2 += p2;
      if (breakEven === null && k >= gap && c2 >= c1 - 1e-9) breakEven = o.age1 + (k + 1) / 12;
      if (k < m1) { y1 += p1; y2 += p2; if (k % 12 === 11) { rows.push([o.age1 + Math.floor(k / 12), y1, y2, c2 - c1]); y1 = 0; y2 = 0; } }
      if (k >= m1 && breakEven !== null) break;
    }
    return { v1: v1, v2: v2, rows: rows, breakEven: breakEven };
  }

  function showGroups(mode) {
    document.getElementById('pnGroupLump').hidden = mode !== 'lump';
    document.getElementById('pnGroupSurv').hidden = mode !== 'survivor';
    document.getElementById('pnGroupLater').hidden = mode !== 'later';
  }

  function fill(rows) {
    var body = document.getElementById('pnSchedule');
    body.textContent = '';
    rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [row[0], money.format(row[1]), money.format(row[2]), (row[3] < -0.5 ? '-' : '') + money.format(Math.abs(row[3]))]
        .forEach(function (v) { var td = document.createElement('td'); td.textContent = v; tr.appendChild(td); });
      body.appendChild(tr);
    });
  }

  function winner(a, b, nameA, nameB) {
    if (Math.abs(a - b) < 0.5) return 'About equal';
    return a > b ? nameA : nameB;
  }

  function update() {
    var mode = document.getElementById('pnMode').value;
    showGroups(mode);
    var life = Math.round(num('pnLife')), ret = num('pnReturn'), cola = num('pnCola');
    var error = document.getElementById('pnError');
    var bad = [life, ret, cola].some(isNaN) || life > 120 || ret < 0 || ret > 20 || cola < 0 || cola > 10, msg = '';
    var o = { life: life, ret: ret / 100, cola: cola / 100 };
    if (mode === 'lump') {
      o.age = Math.round(num('pnRetAge')); o.L = num('pnLump'); o.P = num('pnMonthly');
      bad = bad || [o.age, o.L, o.P].some(isNaN) || o.age < 40 || o.age > 90 || life <= o.age || o.L < 0 || o.P < 0;
      msg = 'Enter a starting age from 40 to 90, a life expectancy above it (up to 120), non-negative amounts, a return up to 20% and an increase up to 10%.';
    } else if (mode === 'survivor') {
      o.age = Math.round(num('pnSvAge')); o.spAge = Math.round(num('pnSpAge')); o.spLife = Math.round(num('pnSpLife'));
      o.single = num('pnSingle'); o.joint = num('pnJoint'); o.survPct = num('pnSurvPct') / 100;
      bad = bad || [o.age, o.spAge, o.spLife, o.single, o.joint, o.survPct].some(isNaN) || o.age < 40 || o.age > 90 ||
            life <= o.age || o.spAge < 18 || o.spAge > 100 || o.spLife <= o.spAge || o.spLife > 120 || o.single < 0 ||
            o.joint < 0 || o.survPct < 0 || o.survPct > 1;
      msg = 'Check the ages (each life expectancy must be above the current age, up to 120), use non-negative amounts and a survivor share from 0 to 100%.';
    } else {
      o.age1 = Math.round(num('pnAge1')); o.age2 = Math.round(num('pnAge2')); o.pay1 = num('pnPay1'); o.pay2 = num('pnPay2');
      bad = bad || [o.age1, o.age2, o.pay1, o.pay2].some(isNaN) || o.age1 < 40 || o.age1 > 90 || o.age2 <= o.age1 ||
            o.age2 > 95 || life <= o.age1 || o.pay1 < 0 || o.pay2 < 0;
      msg = 'Option 2 must start later than option 1, both from age 40, with a life expectancy above the first age (up to 120) and non-negative amounts.';
    }
    error.hidden = !bad;
    if (bad) { error.textContent = msg; return; }

    if (mode === 'lump') {
      var r = lumpMode(o);
      set('pnWinner', winner(r.value, o.L, 'Monthly pension', 'Lump sum'));
      set('pnL2', 'Value of the pension'); set('pnV2', money.format(r.value));
      set('pnL3', 'Lump sum'); set('pnV3', money.format(o.L));
      set('pnL4', 'Difference'); set('pnV4', money.format(Math.abs(r.value - o.L)));
      set('pnSummary', r.implied === null ? 'The pension\'s implied return can\'t be worked out from these amounts.' :
          'The pension is worth the same as the lump sum at an investment return of ' + pct.format(r.implied) +
          ' a year. If you expect to earn more than that, the lump sum is worth more.');
      set('pnNote', r.lastsMonths === null ? 'Paying yourself the same income from the lump sum, it would last beyond age 120.' :
          'Paying yourself the same income from the lump sum, it would run out at about age ' + fmtAge(o.age + r.lastsMonths / 12) +
          (o.age + r.lastsMonths / 12 < life ? ', before your life expectancy.' : ', after your life expectancy.'));
      set('pnH2', 'Pension paid'); set('pnH3', 'Total received'); set('pnH4', 'Lump sum balance');
      set('pnScheduleNote', 'Pension received each year, and what is left of the lump sum if you withdraw the same amounts.');
      fill(r.rows);
    } else if (mode === 'survivor') {
      var s = survivorMode(o);
      set('pnWinner', winner(s.joint, s.single, 'Joint and survivor', 'Single life'));
      set('pnL2', 'Single-life value'); set('pnV2', money.format(s.single));
      set('pnL3', 'Joint-and-survivor value'); set('pnV3', money.format(s.joint));
      set('pnL4', 'Difference'); set('pnV4', money.format(Math.abs(s.joint - s.single)));
      set('pnSummary', 'Total paid: ' + money.format(s.totS) + ' as a single-life pension and ' + money.format(s.totJ) +
          ' as a joint-and-survivor pension.');
      set('pnNote', s.survYears > 0 ? 'Your spouse would receive ' + money.format(s.surv) + ' a month (before increases) for about ' +
          s.survYears + ' years after your life expectancy.' : 'Your spouse\'s life expectancy ends before yours, so no survivor payments are counted.');
      set('pnH2', 'Single life'); set('pnH3', 'Joint and survivor'); set('pnH4', 'Joint minus single, total');
      set('pnScheduleNote', 'Payments each year by your age, including survivor payments after your life expectancy.');
      fill(s.rows);
    } else {
      var w = laterMode(o);
      set('pnWinner', winner(w.v2, w.v1, 'Retire at ' + o.age2, 'Retire at ' + o.age1));
      set('pnL2', 'Value retiring at ' + o.age1); set('pnV2', money.format(w.v1));
      set('pnL3', 'Value retiring at ' + o.age2); set('pnV3', money.format(w.v2));
      set('pnL4', 'Difference'); set('pnV4', money.format(Math.abs(w.v2 - w.v1)));
      set('pnSummary', 'Both values are measured at age ' + o.age1 + ', so the later pension is discounted for the wait.');
      set('pnNote', w.breakEven === null ? 'The later pension never catches up in total dollars received before age 120.' :
          'Break-even: by about age ' + fmtAge(w.breakEven) + ' the later pension has paid out as much in total as the earlier one' +
          (w.breakEven <= life ? ', which is before your life expectancy.' : ', which is after your life expectancy.'));
      set('pnH2', 'Retire at ' + o.age1); set('pnH3', 'Retire at ' + o.age2); set('pnH4', 'Later minus earlier, total');
      set('pnScheduleNote', 'Pension received each year under each option, up to your life expectancy.');
      fill(w.rows);
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('pnForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
